import math
docs = {"d1": "archive search deep index", "d2": "archive search",
        "d3": "xylophone zephyr quixotic archive"}
N = len(docs)
df = {}
for text in docs.values():
    for term in set(text.split()):
        df[term] = df.get(term, 0) + 1
def rarity(text):
    return sum(math.log(N / df[t]) for t in text.split())
for d, t in sorted(docs.items(), key=lambda kv: -rarity(kv[1])):
    print("%s rarity=%.2f :: %s" % (d, rarity(t), t))

