import math
lengths = {"d1": 120, "d2": 95, "d3": 110, "d4": 2500, "d5": 105}
vals = list(lengths.values())
mean = sum(vals) / len(vals)
sd = math.sqrt(sum((v - mean) ** 2 for v in vals) / len(vals))
for d, v in lengths.items():
    z = (v - mean) / sd
    if abs(z) > 1.5:
        print("outlier %s: length=%d z=%.1f" % (d, v, z))

